export function detailedServiceCoverage(region: Region, service: string, lang: "en" | "ar", covers: readonly string[]) {
  if (service === "urgent-legal-assistance") return [];
  const localeIndex = lang === "en" ? 0 : 1;
  if (region !== "uae" && service === "tax-zakat") return (region === "sa" ? saudiTaxCoverage : syrianTaxCoverage).map(item => ({ title: item.title[localeIndex], text: item.text[localeIndex] }));
  const source = region === "uae" ? getUaeService(service)?.covers : BILINGUAL_SERVICE_COVERAGE[service];
  if (!source) throw new Error(`Missing service coverage source: ${region}/${service}`);
  return covers.map(title => {
    const index = source[lang].indexOf(title);
    const key = source.en[index];
    const detail = index < 0 ? undefined : details[key] ?? details[equivalents[key]];
    if (!detail) throw new Error(`Missing detailed service coverage: ${region}/${service}/${lang}: ${title}`);
    return { title, text: detail[localeIndex] };
  });
}
